      "slug": "imposto-seletivo-governo-envia-medida-ao-congresso-e-garante-manutenca",
      "pagina_local": "imposto-seletivo-governo-envia-medida-ao-congresso-e-garante-manutenca.html",
      "link_oficial": "https://agenciabrasil.ebc.com.br/economia/noticia/2026-11/governo-quer-enviar-mp-do-imposto-seletivo-ainda-hoje-ao-congresso",
